UPDATE pull_task
SET deleted_at = #{deletedAt}, updated_at = #{deletedAt}
WHERE deleted_at IS NULL
  AND id IN
  #{id}
  AND (
    (task_type = 'GROUP_MARKETING' AND status = 'DRAFT')
    OR
    (task_type = 'STANDARD' AND status IN ('WAIT_START', 'COMPLETED', 'ENDED'))
  )
